let tunnelInfo = null; // { state, url, type, error, startedAt, retryAt }
let activeTunnel = null; // { close, onExit, isAlive, healthCheck }
// How many probes in a row must fail before the connector is thrown away.
// One probe on a busy runner can time out while the tunnel is perfectly alive,
// and reopening on the first failure is its own kind of 1033: the panel keeps
// the old address for the whole window until the new one passes its own check.
// The shell keeper already uses this rule (MAIN_FAILS >= 3 in
// tools/tunnel_keeper.sh) - the hub now answers with the same patience.
const TUNNEL_HEALTH_FAILS = parseInt(process.env.TUNNEL_HEALTH_FAILS || '3', 10) || 3;

