input.newString:
// A connector can remain as a process while its edge connection is lost.
    // Process liveness alone is therefore insufficient to prevent Error 1033.
    let healthFails = 0;
    if (typeof result.healthCheck === 'function') {
      tunnelHealthTimer = setInterval(async () => {
        if (tunnelStopped || activeTunnel !== result) return;
        let reason = null;
        try {
          const health = await result.healthCheck();
          if (health && health.ok) { healthFails = 0; return; }
          reason = `HTTP ${health && health.status || 'нет ответа'}`;
        } catch (e) {
          reason = e.message;
        }
        healthFails += 1;
        if (healthFails < TUNNEL_HEALTH_FAILS) {
          console.log(`  ⚠ public tunnel probe ${healthFails}/${TUNNEL_HEALTH_FAILS} failed (${reason}); URL kept until it fails again.`);
          return;
        }
        try { result.close(); } catch {}
        reconnect(`public tunnel health check failed ${healthFails} probes in a row (${reason})`);
      }, 30000);
      tunnelHealthTimer.unref?.();
    }

